// PREMIUM VOICE (Luis, 6 Oct): Gemini TTS for development and production.
//
// Same behaviour as the local plugin (scripts/vite-premium-voice.mjs):
//   POST { text, lang } -> audio/wav, generated by Gemini (gemini-3.8-flash-lite-tts, voice Kore).
//   Each text is generated once and saved in the private "premium-tts" bucket for everyone, so
//   playing it again costs nothing.
// Secrets: GEMINI_ENTERPRISE_API_KEY (+ GOOGLE_CLOUD_PROJECT), GOOGLE_CLOUD_TTS_API_KEY and/or
// GEMINI_API_KEY (without any of them the function answers 404 and the app keeps its old voices);
// optional: GOOGLE_CLOUD_TTS_VOICE, PREMIUM_TTS_ENGINE, GEMINI_TTS_MODEL,
// GEMINI_TTS_BACKUP_MODELS, GEMINI_TTS_VOICE and PREMIUM_TTS_DAILY_LIMIT.
//
// GOOGLE CLOUD VOICE (Luis, 11 Oct): Gemini only allows 100 new audios a day and 10 a minute for the
// whole project, too little for 50 students. With GOOGLE_CLOUD_TTS_API_KEY the voice comes from
// Google Cloud Text-to-Speech (Chirp 3 HD, voice Kore: 200 a minute, no daily cap, about 30 $ per
// million letters) and Gemini is only the backup. PREMIUM_TTS_ENGINE=gemini puts Gemini first. Each
// engine keeps its own saved audios, so one word always sounds with one voice.
// Every audio adds to public.premium_tts_daily_usage (migration 20261006130000), which the admin
// panel reads and which caps how many new audios one student can create per day.
import { createClient } from 'https://esm.sh/@supabase/supabase-js@2'
import { CORS_HEADERS, jsonResponse } from '../_shared/http.ts'

const DEFAULT_MODEL = 'gemini-3.8-flash-lite-tts'
/** Used when the main model has no new audios left today (see GEMINI DAILY LIMIT below). */
const DEFAULT_BACKUP_MODELS = 'gemini-3.8-flash-tts'
const DEFAULT_VOICE = 'Kore'
// New audios one student can create per day (Luis, 11 Oct: 500 so that the first days, when everyone
// listens to all the words they already had, nobody runs out; already made audios do not count).
const DEFAULT_DAILY_LIMIT = 500
const MAX_TEXT_CHARS = 600
const BUCKET = 'premium-tts'
const LANG_PATTERN = /^[a-z]{2,3}(-[A-Z]{2})?$/

// Paid tier prices per million tokens (ai.google.dev/gemini-api/docs/pricing, October 2026);
// they double from 1 January 2027. Same table as the local plugin.
const PRICES: Record<string, { input: [number, number]; output: [number, number] }> = {
  'gemini-3.8-flash-lite-tts': { input: [0.5, 1], output: [6, 12] },
  'gemini-3.8-flash-tts': { input: [0.5, 1], output: [9, 18] },
}
const PRICE_CHANGE_DAY = '2027-01-01'
/** Gemini counts 25 audio tokens per second when the answer does not say. */
const AUDIO_TOKENS_PER_SECOND = 25

type Bytes = Uint8Array<ArrayBuffer>
type DbError = { message: string } | null

/** Only what this function uses of the service-role client (same approach as pronunciation-cache.ts). */
type AdminClient = {
  rpc: (fn: string, args: Record<string, unknown>) => PromiseLike<{ data: unknown; error: DbError }>
  from: (table: string) => {
    select: (columns: string) => {
      eq: (column: string, value: string) => {
        eq: (column: string, value: string) => PromiseLike<{ data: unknown; error: DbError }>
      }
    }
  }
  storage: {
    from: (bucket: string) => {
      download: (path: string) => PromiseLike<{ data: Blob | null; error: DbError }>
      upload: (
        path: string,
        body: Bytes,
        options: { contentType: string; upsert: boolean },
      ) => PromiseLike<{ error: DbError }>
    }
  }
}

function audioResponse(audio: Bytes): Response {
  return new Response(audio, {
    status: 200,
    headers: {
      ...CORS_HEADERS,
      'Content-Type': 'audio/wav',
      'Cache-Control': 'private, max-age=86400',
    },
  })
}

async function requireUserId(req: Request): Promise<string | null> {
  const authHeader = req.headers.get('Authorization')
  const supabaseUrl = Deno.env.get('SUPABASE_URL')
  const supabaseAnonKey = Deno.env.get('SUPABASE_ANON_KEY')
  if (!authHeader || !supabaseUrl || !supabaseAnonKey) return null
  const client = createClient(supabaseUrl, supabaseAnonKey, {
    global: { headers: { Authorization: authHeader } },
  })
  const { data, error } = await client.auth.getUser()
  if (error || !data.user) return null
  return data.user.id
}

function createAdminClient(): AdminClient | null {
  const supabaseUrl = Deno.env.get('SUPABASE_URL')
  const serviceRoleKey = Deno.env.get('SUPABASE_SERVICE_ROLE_KEY')
  if (!supabaseUrl || !serviceRoleKey) return null
  return createClient(supabaseUrl, serviceRoleKey, {
    auth: { persistSession: false, autoRefreshToken: false },
  }) as unknown as AdminClient
}

async function sha1Hex(value: string): Promise<string> {
  const digest = await crypto.subtle.digest('SHA-1', new TextEncoder().encode(value))
  return Array.from(new Uint8Array(digest), (byte) => byte.toString(16).padStart(2, '0')).join('')
}

function base64ToBytes(value: string): Bytes {
  const binary = atob(value)
  const bytes = new Uint8Array(binary.length)
  for (let index = 0; index < binary.length; index += 1) bytes[index] = binary.charCodeAt(index)
  return bytes
}

function isWav(bytes: Uint8Array): boolean {
  return bytes.length >= 44 && String.fromCharCode(...bytes.subarray(0, 4)) === 'RIFF'
}

/** Gemini answers raw 16-bit mono PCM: wrap it in a WAV header so every browser can play it. */
function pcmToWav(pcm: Bytes, rate: number): Bytes {
  const wav = new Uint8Array(44 + pcm.length)
  const view = new DataView(wav.buffer)
  const writeAscii = (offset: number, text: string) => {
    for (let index = 0; index < text.length; index += 1) wav[offset + index] = text.charCodeAt(index)
  }
  writeAscii(0, 'RIFF')
  view.setUint32(4, 36 + pcm.length, true)
  writeAscii(8, 'WAVE')
  writeAscii(12, 'fmt ')
  view.setUint32(16, 16, true)
  view.setUint16(20, 1, true)
  view.setUint16(22, 1, true)
  view.setUint32(24, rate, true)
  view.setUint32(28, rate * 2, true)
  view.setUint16(32, 2, true)
  view.setUint16(34, 16, true)
  writeAscii(36, 'data')
  view.setUint32(40, pcm.length, true)
  wav.set(pcm, 44)
  return wav
}

function wavSeconds(wav: Uint8Array): number {
  if (!isWav(wav)) return 0
  const byteRate = new DataView(wav.buffer, wav.byteOffset, wav.byteLength).getUint32(28, true) || 48000
  return Math.max(0, (wav.length - 44) / byteRate)
}

function priceUsd(model: string, inputTokens: number, outputTokens: number): number {
  const prices = PRICES[model] || PRICES[DEFAULT_MODEL]
  const day = new Date().toISOString().slice(0, 10)
  const step = day >= PRICE_CHANGE_DAY ? 1 : 0
  return (inputTokens * prices.input[step] + outputTokens * prices.output[step]) / 1_000_000
}

type Generated = { audio: Bytes; seconds: number; inputTokens: number; outputTokens: number; chars?: number }

// GEMINI BUSY (Luis, 11 Oct): Gemini only accepts a few new audios per minute for this project and
// answers 429 to the rest (it happened in development: 39 at once). A 429 waits what Gemini asks for
// (RetryInfo, at most MAX_WAIT_SECONDS) and tries again; if it is still busy the app gets 503 with
// `retryAfter`, so it tries later instead of switching to the old voices.
const GEMINI_TRIES = 3
const MAX_WAIT_SECONDS = 12

class GeminiBusyError extends Error {
  retryAfter: number
  constructor(message: string, retryAfter: number) {
    super(message)
    this.retryAfter = retryAfter
  }
}

// GEMINI DAILY LIMIT (Luis, 11 Oct): Google only lets a project make 100 audios a day with each
// Gemini 3.8 TTS model (quota GenerateRequestsPerDayPerProjectPerModel; on 9 Oct development made
// 102 and then everything failed). That quota is per model, so when the main model runs out the
// backup models (same voice) are used, and when all are out the app gets 503 VOICE_DAY_LIMIT and
// does not keep retrying. The quota comes back at midnight Pacific time.
/** A Gemini answer that is not audio (status kept to tell setup errors from one-off failures). */
class GeminiHttpError extends Error {
  status: number
  constructor(message: string, status: number) {
    super(message)
    this.status = status
  }
}

class GeminiDayLimitError extends Error {
  retryAfter: number
  constructor(message: string, retryAfter: number) {
    super(message)
    this.retryAfter = retryAfter
  }
}

/** Models with no audios left today, until when (ms). Only for this instance of the function. */
const exhaustedUntil = new Map<string, number>()

/** Seconds until midnight in Pacific time, when Google resets the daily quotas. */
function secondsUntilQuotaReset(now = new Date()): number {
  const parts = Object.fromEntries(
    new Intl.DateTimeFormat('en-US', {
      timeZone: 'America/Los_Angeles',
      hour12: false,
      hour: '2-digit',
      minute: '2-digit',
      second: '2-digit',
    })
      .formatToParts(now)
      .map((part) => [part.type, part.value]),
  )
  const elapsed = (Number(parts.hour) % 24) * 3600 + Number(parts.minute) * 60 + Number(parts.second)
  return Math.max(60, 86400 - elapsed)
}

/** Whether a Gemini 429 is the daily quota (not the per-minute one). */
function isDailyQuota(data: unknown): boolean {
  const error = (data as { error?: { message?: unknown; details?: unknown } })?.error
  const details = Array.isArray(error?.details) ? error.details : []
  for (const detail of details) {
    const violations = (detail as { violations?: unknown })?.violations
    if (!Array.isArray(violations)) continue
    for (const violation of violations) {
      const { quotaId, quotaMetric } = (violation || {}) as { quotaId?: unknown; quotaMetric?: unknown }
      if (/per_?day/i.test(`${quotaId ?? ''} ${quotaMetric ?? ''}`)) return true
    }
  }
  return /per[ _]?day/i.test(String(error?.message ?? ''))
}

function geminiRetrySeconds(data: unknown): number | null {
  const details = (data as { error?: { details?: unknown } })?.error?.details
  if (!Array.isArray(details)) return null
  for (const detail of details) {
    const match = /^(\d+(?:\.\d+)?)s$/.exec(String((detail as { retryDelay?: unknown })?.retryDelay || ''))
    if (match) return Math.ceil(Number(match[1]))
  }
  return null
}

// SHORT TEXTS (Luis, 11 Oct): with a single word Gemini sometimes runs on into a next word
// («dzień d…», as if starting «dzień dobry»). For one to three words it gets a full stop and an
// instruction to say only that and stop, and those audios are cached under a new key so the old
// ones are made again.
const SHORT_TEXT_MAX_WORDS = 3

function isShortText(text: string): boolean {
  return text.trim().split(/\s+/).length <= SHORT_TEXT_MAX_WORDS
}

function speakableText(text: string): string {
  const clean = text.trim()
  return isShortText(clean) && !/[.!?…。！？]$/.test(clean) ? `${clean}.` : clean
}

function cacheKeySource(model: string, voice: string, lang: string, text: string): string {
  const base = `${model}|${voice}|${lang}|${text}`
  return isShortText(text) ? `${base}|short-v2` : base
}

// GEMINI ENTERPRISE (Luis, 11 Oct): the same Gemini voice through Google's business platform
// (formerly Vertex AI), without AI Studio's 100-a-day cap. Tested locally: 120 new audios in 48 s.
// Secrets: GEMINI_ENTERPRISE_API_KEY (an API key bound to a service account with the role «Usuario
// de Agent Platform») and GOOGLE_CLOUD_PROJECT (the project number). Its voice field may be written
// differently from AI Studio's, so the accepted one is remembered.
type GeminiRoute = { via: 'studio' | 'enterprise'; key: string; project?: string }
let enterpriseVoiceFormat: 'voice' | 'prebuilt' = 'voice'
let enterpriseBrokenUntil = 0

async function generateWithGemini(
  route: GeminiRoute,
  model: string,
  voice: string,
  text: string,
  lang: string,
): Promise<Generated> {
  const languageName = new Intl.DisplayNames(['en'], { type: 'language' }).of(lang) || lang
  const url =
    route.via === 'enterprise'
      ? route.project
        ? `https://aiplatform.googleapis.com/v1/projects/${route.project}/locations/global/publishers/google/models/${model}:generateContent`
        : `https://aiplatform.googleapis.com/v1/publishers/google/models/${model}:generateContent`
      : `https://generativelanguage.googleapis.com/v1beta/models/${model}:generateContent`
  const voiceConfig = (format: 'voice' | 'prebuilt') =>
    format === 'prebuilt' ? { voiceConfig: { prebuiltVoiceConfig: { voiceName: voice } } } : { voiceConfig: { voice } }
  const call = async (withStyle: boolean, format: 'voice' | 'prebuilt' = route.via === 'enterprise' ? enterpriseVoiceFormat : 'voice') => {
    const short = isShortText(text)
    const part: Record<string, unknown> = { text: speakableText(text) }
    if (withStyle) {
      part.speech_metadata = {
        style:
          `Native ${languageName} speaker (${lang}). Read it in ${languageName}, clearly and naturally, like a friendly teacher.` +
          (short ? ' Say only these exact words, once, and then stop. Do not add any other word or sound.' : ''),
      }
    }
    const response = await fetch(url, {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-goog-api-key': route.key },
      body: JSON.stringify({
        contents: [{ role: 'user', parts: [part] }],
        generationConfig: { responseModalities: ['AUDIO'], speechConfig: voiceConfig(format) },
      }),
    })
    const data = await response.json().catch(() => ({}))
    if (route.via === 'enterprise' && response.ok) enterpriseVoiceFormat = format
    if (route.via === 'enterprise' && !response.ok) {
      console.warn('premium-tts enterprise', response.status, String(data?.error?.message || '').slice(0, 300))
    }
    return { response, data }
  }

  let { response, data } = await call(true)
  for (let attempt = 1; ; attempt += 1) {
    // If this model does not accept the style field, try once with the plain text.
    if (response.status === 400) ({ response, data } = await call(false))
    if (response.status === 400 && route.via === 'enterprise') {
      ;({ response, data } = await call(false, enterpriseVoiceFormat === 'voice' ? 'prebuilt' : 'voice'))
    }
    // 500: Gemini sometimes fails one answer; it is retried like «busy».
    if (response.status !== 429 && response.status !== 503 && response.status !== 500) break
    if (response.status === 429 && isDailyQuota(data)) {
      throw new GeminiDayLimitError(`Gemini TTS daily limit (${model})`, secondsUntilQuotaReset())
    }
    const retryAfter = Math.min(MAX_WAIT_SECONDS, geminiRetrySeconds(data) ?? (response.status === 500 ? 1 : 4 * attempt))
    if (attempt >= GEMINI_TRIES) throw new GeminiBusyError(`Gemini TTS ${response.status}`, retryAfter)
    await new Promise((resolve) => setTimeout(resolve, retryAfter * 1000))
    ;({ response, data } = await call(true))
  }
  if (!response.ok) throw new GeminiHttpError(`Gemini TTS ${response.status}`, response.status)

  const parts = data?.candidates?.[0]?.content?.parts || []
  const inline = parts.find((part: { inlineData?: { data?: string } }) => part?.inlineData?.data)?.inlineData
  if (!inline?.data) throw new GeminiHttpError('Gemini TTS: no audio in the answer', 502)
  const bytes = base64ToBytes(inline.data)
  const rate = Number(/rate=(\d+)/.exec(inline.mimeType || '')?.[1]) || 24000
  const audio = isWav(bytes) ? bytes : pcmToWav(bytes, rate)
  const seconds = wavSeconds(audio)
  const meta = data?.usageMetadata || {}
  return {
    audio,
    seconds,
    inputTokens: Number(meta.promptTokenCount) || Math.ceil((text.length + 120) / 4),
    outputTokens: Number(meta.candidatesTokenCount) || Math.ceil(seconds * AUDIO_TOKENS_PER_SECOND),
  }
}

/** The main model, or a backup one when the main one has no audios left today. */
async function generateWithAnyModel(
  routes: GeminiRoute[],
  models: string[],
  voice: string,
  text: string,
  lang: string,
): Promise<{ generated: Generated; model: string; via: GeminiRoute['via'] }> {
  let lastError: unknown = null
  let skippedForToday = false
  for (const route of routes) {
    if (route.via === 'enterprise' && enterpriseBrokenUntil > Date.now()) continue
    for (const name of models) {
      const slot = `${route.via}:${name}`
      if ((exhaustedUntil.get(slot) ?? 0) > Date.now()) {
        skippedForToday = true
        continue
      }
      try {
        return { generated: await generateWithGemini(route, name, voice, text, lang), model: name, via: route.via }
      } catch (error) {
        lastError = error
        if (error instanceof GeminiDayLimitError) {
          console.warn('premium-tts: no audios left today with', name, route.via)
          exhaustedUntil.set(slot, Date.now() + error.retryAfter * 1000)
          continue
        }
        if (route.via === 'enterprise') {
          // Not set up (no permission, wrong project, model not found): skip it for 10 minutes.
          // Any other failure only affects this text: the next route tries it.
          if (error instanceof GeminiHttpError && [401, 403, 404].includes(error.status)) {
            enterpriseBrokenUntil = Date.now() + 10 * 60_000
            break
          }
          continue
        }
        throw error
      }
    }
  }
  if (lastError === null && !skippedForToday) throw new GeminiBusyError('Gemini TTS: no route available now', 30)
  if (lastError !== null && !(lastError instanceof GeminiDayLimitError)) throw lastError
  throw new GeminiDayLimitError('Gemini TTS daily limit (all models)', secondsUntilQuotaReset())
}

const CLOUD_TTS_USD_PER_CHAR = 30 / 1_000_000
type Engine = 'cloud' | 'gemini'
/** Languages Google Cloud has no Chirp 3 HD voice for, in this instance (they go to Gemini). */
const cloudUnsupported = new Set<string>()

/** Chirp 3 HD names a few languages differently from the app. */
function cloudLocale(lang: string): string {
  return ({ 'zh-CN': 'cmn-CN', 'ar-SA': 'ar-XA', 'no-NO': 'nb-NO' } as Record<string, string>)[lang] || lang
}

async function generateWithCloud(apiKey: string, voice: string, text: string, lang: string): Promise<Generated> {
  const locale = cloudLocale(lang)
  for (let attempt = 1; ; attempt += 1) {
    const response = await fetch('https://texttospeech.googleapis.com/v1/text:synthesize', {
      method: 'POST',
      headers: { 'Content-Type': 'application/json', 'x-goog-api-key': apiKey },
      body: JSON.stringify({
        input: { text: speakableText(text) },
        voice: { languageCode: locale, name: `${locale}-Chirp3-HD-${voice}` },
        audioConfig: { audioEncoding: 'LINEAR16', sampleRateHertz: 24000 },
      }),
    })
    const data = await response.json().catch(() => ({}))
    if ((response.status === 429 || response.status === 503) && attempt < 3) {
      await new Promise((resolve) => setTimeout(resolve, 1500 * attempt))
      continue
    }
    // Only a language without a Chirp voice is remembered (not one text Google did not like).
    if (response.status === 400 && /voice|language/i.test(String(data?.error?.message || ''))) cloudUnsupported.add(lang)
    if (!response.ok || !data?.audioContent) {
      throw new Error(`Cloud TTS ${response.status}: ${String(data?.error?.message || 'no audio').slice(0, 200)}`)
    }
    const bytes = base64ToBytes(String(data.audioContent))
    const audio = isWav(bytes) ? bytes : pcmToWav(bytes, 24000)
    return { audio, seconds: wavSeconds(audio), inputTokens: 0, outputTokens: 0 }
  }
}

async function track(
  admin: AdminClient,
  userId: string,
  model: string,
  generated: Generated | null,
): Promise<number | null> {
  const { data, error } = await admin.rpc('premium_tts_track', {
    p_user_id: userId,
    p_model: model,
    p_generated: Boolean(generated),
    p_seconds: generated ? Math.round(generated.seconds * 100) / 100 : 0,
    p_input_tokens: generated?.inputTokens ?? 0,
    p_output_tokens: generated?.outputTokens ?? 0,
    p_cost_usd: generated
      ? model === 'chirp3-hd'
        ? (generated.chars ?? 0) * CLOUD_TTS_USD_PER_CHAR
        : priceUsd(model, generated.inputTokens, generated.outputTokens)
      : 0,
  })
  if (error) {
    console.warn('premium-tts: usage not saved', error.message)
    return null
  }
  return typeof data === 'number' ? data : null
}

async function generatedToday(admin: AdminClient, userId: string): Promise<number> {
  const day = new Date().toISOString().slice(0, 10)
  const { data, error } = await admin
    .from('premium_tts_daily_usage')
    .select('generated')
    .eq('day', day)
    .eq('user_id', userId)
  if (error || !Array.isArray(data)) return 0
  return data.reduce((sum, row) => sum + (Number((row as { generated?: number }).generated) || 0), 0)
}

Deno.serve(async (req) => {
  if (req.method === 'OPTIONS') return new Response('ok', { headers: CORS_HEADERS })
  if (req.method !== 'POST') return jsonResponse(405, { error: 'Method not allowed' })

  // No key = premium voice off: 404 tells the app to stop asking and use its old voices.
  const apiKey = Deno.env.get('GEMINI_API_KEY') || ''
  const enterpriseKey = Deno.env.get('GEMINI_ENTERPRISE_API_KEY') || ''
  const cloudKey = Deno.env.get('GOOGLE_CLOUD_TTS_API_KEY') || ''
  const engineSetting = Deno.env.get('PREMIUM_TTS_ENGINE')
  const geminiFirst = engineSetting === 'gemini' || (Boolean(enterpriseKey) && engineSetting !== 'cloud')
  const engines = ((geminiFirst ? ['gemini', 'cloud'] : ['cloud', 'gemini']) as Engine[])
    .filter((engine) => (engine === 'cloud' ? Boolean(cloudKey) : Boolean(apiKey || enterpriseKey)))
  const geminiRoutes: GeminiRoute[] = [
    ...(enterpriseKey ? [{ via: 'enterprise' as const, key: enterpriseKey, project: Deno.env.get('GOOGLE_CLOUD_PROJECT') || '' }] : []),
    ...(apiKey ? [{ via: 'studio' as const, key: apiKey }] : []),
  ]
  if (engines.length === 0) return jsonResponse(404, { error: 'Premium voice is off' })

  const userId = await requireUserId(req)
  if (!userId) return jsonResponse(401, { error: 'Unauthorized' })

  let text = ''
  let lang = ''
  try {
    const body = await req.json()
    text = String(body?.text ?? '').trim()
    lang = String(body?.lang ?? '')
  } catch {
    return jsonResponse(400, { error: 'Invalid JSON body' })
  }
  if (!text || text.length > MAX_TEXT_CHARS || !LANG_PATTERN.test(lang)) {
    return jsonResponse(400, { error: 'Bad request' })
  }

  const admin = createAdminClient()
  if (!admin) return jsonResponse(500, { error: 'Supabase function environment is not configured' })

  const model = Deno.env.get('GEMINI_TTS_MODEL') || DEFAULT_MODEL
  const backupModels = (Deno.env.get('GEMINI_TTS_BACKUP_MODELS') ?? DEFAULT_BACKUP_MODELS)
    .split(',')
    .map((name) => name.trim())
    .filter((name) => name && name !== model)
  const voice = Deno.env.get('GEMINI_TTS_VOICE') || DEFAULT_VOICE
  const dailyLimit = Number(Deno.env.get('PREMIUM_TTS_DAILY_LIMIT')) || DEFAULT_DAILY_LIMIT
  const cloudVoice = Deno.env.get('GOOGLE_CLOUD_TTS_VOICE') || DEFAULT_VOICE
  /** Where each engine saves this text (each engine its own audios: one word, one voice). */
  const pathFor = async (engine: Engine): Promise<string> =>
    engine === 'cloud'
      ? `chirp3-hd/${cloudVoice}/${await sha1Hex(`cloud|chirp3-hd|${cloudVoice}|${lang}|${text}`)}.wav`
      : `${model}/${voice}/${await sha1Hex(cacheKeySource(model, voice, lang, text))}.wav`
  const usageModel = (engine: Engine): string => (engine === 'cloud' ? 'chirp3-hd' : model)

  // Already generated by anyone: free.
  const primaryPath = await pathFor(engines[0])
  const cached = await admin.storage.from(BUCKET).download(primaryPath)
  if (!cached.error && cached.data) {
    await track(admin, userId, usageModel(engines[0]), null)
    return audioResponse(new Uint8Array(await cached.data.arrayBuffer()))
  }

  // Cost guard: a student cannot create more than PREMIUM_TTS_DAILY_LIMIT new audios a day.
  // Over it, only NEW texts use the old voices until tomorrow; the saved ones keep the premium voice.
  if ((await generatedToday(admin, userId)) >= dailyLimit) {
    return jsonResponse(429, { error: 'Daily premium voice limit reached', code: 'DAILY_LIMIT' })
  }

  let lastError: unknown = null
  for (const engine of engines) {
    const path = await pathFor(engine)
    if (engine !== engines[0]) {
      // The backup engine may already have this text saved from an earlier failure.
      const saved = await admin.storage.from(BUCKET).download(path)
      if (!saved.error && saved.data) {
        await track(admin, userId, usageModel(engine), null)
        return audioResponse(new Uint8Array(await saved.data.arrayBuffer()))
      }
    }
    if (engine === 'cloud' && cloudUnsupported.has(lang)) continue
    try {
      let generated: Generated
      let madeBy = usageModel(engine)
      let via = 'cloud'
      if (engine === 'cloud') {
        generated = { ...(await generateWithCloud(cloudKey, cloudVoice, text, lang)), chars: text.length }
      } else {
        // Saved under the main model's name whichever Gemini model made it: it is the same voice.
        const made = await generateWithAnyModel(geminiRoutes, [model, ...backupModels], voice, text, lang)
        generated = made.generated
        madeBy = made.model
        via = made.via
      }
      const upload = await admin.storage.from(BUCKET).upload(path, generated.audio, {
        contentType: 'audio/wav',
        upsert: true,
      })
      if (upload.error) console.warn('premium-tts: audio not cached', upload.error.message)
      await track(admin, userId, madeBy, generated)
      // One line per new audio, to see in the logs which route made it (enterprise, studio or cloud).
      console.log('premium-tts new audio', madeBy, via)
      return audioResponse(generated.audio)
    } catch (error) {
      lastError = error
      console.warn(`premium-tts ${engine} failed`, error instanceof Error ? error.message : String(error))
    }
  }

  if (lastError instanceof GeminiDayLimitError) {
    return jsonResponse(503, { error: 'Premium voice daily limit', code: 'VOICE_DAY_LIMIT', retryAfter: lastError.retryAfter })
  }
  if (lastError instanceof GeminiBusyError) {
    return jsonResponse(503, { error: 'Premium voice busy', code: 'VOICE_BUSY', retryAfter: lastError.retryAfter })
  }
  return jsonResponse(502, { error: 'Premium voice failed', code: 'VOICE_FAILED', retryAfter: 5 })
})
